<script setup>
import {programDescriptions} from './kiosk/wash-texts.js'
import StationLink from './StationLink.vue'
import ContactSettings from './ContactSettings.vue'
import CustomerCards from './CustomerCards.vue'
import VipMigration from './VipMigration.vue'
import { ref, reactive, computed, onMounted, onUnmounted } from 'vue'
import { api } from './api'
import StationReports from './StationReports.vue'
import TimeSelect from './TimeSelect.vue'
const reportScope=ref('all')
const props = defineProps({ page:String, token:String, language:String, account:Object })
const emit = defineEmits(['dirty','account'])
const tr = (ru,uz,en) => ({ru,uz,en}[props.language] || ru)
const titles = {reports:['Отчёты','Hisobotlar','Reports'],cards:['VIP и карты','VIP va kartalar','VIP & cards'],'kiosk-settings':['Экран мойки','Yuvish ekrani','Wash screen'],telegram:['Telegram','Telegram','Telegram'],account:['Учётная запись','Hisob','Account']}
const busy = ref(false), error = ref(''), notice = ref(''), dirty = ref(false)
const contactDirty=ref(false)
function contactChanged(value){contactDirty.value=value;emit('dirty',dirty.value||value)}
const request = (path,options={}) => api(path,{token:props.token,...options})
const post = (path,data) => request(path,{method:'POST',body:JSON.stringify(data)})
function changed() { dirty.value=true; notice.value=''; emit('dirty',true) }
function clean() { dirty.value=false; emit('dirty',contactDirty.value) }
async function run(fn, saved=false) { if(busy.value)return; busy.value=true; error.value=''; notice.value=''; try { await fn(); if(saved) { clean(); notice.value=tr('Сохранено','Saqlandi','Saved') } } catch(e) { error.value=e.message } finally { busy.value=false } }

const fieldNames = {
accentPrimary:['Основной акцент','Asosiy rang','Primary accent'],accentSecondary:['Дополнительный акцент','Qo‘shimcha rang','Secondary accent'],statusOnline:['Связь установлена','Aloqa mavjud','Online status'],background:['Фон','Fon','Background'],surface:['Карточки','Kartochkalar','Cards'],surfaceRaised:['Выделенная поверхность','Ajratilgan sirt','Raised surface'],text:['Основной текст','Asosiy matn','Main text'],muted:['Второстепенный текст','Qo‘shimcha matn','Secondary text'],danger:['Ошибка','Xato','Error'],warning:['Предупреждение','Ogohlantirish','Warning'],border:['Рамка','Chegara','Border'],glow:['Подсветка','Yoritish','Glow'],
water:['Вода','Suv','Water'],foam:['Пена','Ko‘pik','Foam'],osmos:['Осмос','Osmos','Osmos'],nano:['Нано','Nano','Nano'],wax:['Воск','Mum','Wax'],chem:['Химия','Kimyo','Chemistry'],vacuum:['Пылесос','Changyutgich','Vacuum'],air:['Воздух','Havo','Air'],pause:['Пауза','Pauza','Pause']}
const fieldName = key => fieldNames[key] ? tr(...fieldNames[key]) : key.replace(/([a-z])([A-Z])/g,'$1 $2')
const textLabel = (key,payment=false) => { const dictionary=payment?configLabels.value.payment:configLabels.value.texts; return (dictionary[props.language]?.[key] || dictionary.ru?.[key] || fieldName(key)).slice(0,90) }
const appearanceSelection=computed(()=>config.value?.theme?.appearance?.mode==='auto'?'auto':config.value?.theme?.appearance?.manualTheme||'dark')
async function applyAppearance(event) {
  if(busy.value)return
  const selection=event.target.value
  const previous=JSON.parse(JSON.stringify(config.value.theme.appearance))
  config.value.theme.appearance.mode=selection==='auto'?'auto':'manual'
  if(selection!=='auto')config.value.theme.appearance.manualTheme=selection
  busy.value=true;error.value='';notice.value=''
  try {
    const data=await post('/api/owner/kiosk/appearance',{config:{mode:selection}})
    config.value.theme.appearance.mode=data.appearance.mode
    config.value.theme.appearance.manualTheme=data.appearance.manualTheme
    notice.value=tr('Вид экрана поста применён','Post ekrani ko‘rinishi qo‘llandi','Station appearance applied')
  }catch(e){config.value.theme.appearance=previous;error.value=e.message}
  finally{event.target.value=appearanceSelection.value;busy.value=false}
}
async function saveConfig() {
  const c=config.value
  const a=c.theme.appearance
  if(a.mode==='auto' && (a.lightStart===a.lightEnd || !/^([01]\d|2[0-3]):[0-5]\d$/.test(a.lightStart) || !/^([01]\d|2[0-3]):[0-5]\d$/.test(a.lightEnd)))throw Error(tr('Задайте разные часы начала и конца светлого периода','Yorug‘ davr boshlanishi va tugashini turlicha belgilang','Set different start and end times for the light period'))
  if(!Number.isFinite(c.payment.minAmount) || c.payment.minAmount<1 || !Number.isFinite(c.payment.maxAmount) || c.payment.maxAmount<c.payment.minAmount)throw Error(tr('Проверьте минимальную и максимальную суммы','Minimal va maksimal summalarni tekshiring','Check minimum and maximum amounts'))
  if(c.payment.quickAmounts.some(v=>!Number.isInteger(v)||v<c.payment.minAmount||v>c.payment.maxAmount))throw Error(tr('Быстрые суммы должны быть в пределах лимитов','Tezkor summalar limitlar ichida bo‘lishi kerak','Quick amounts must be within limits'))
  config.value=(await post('/api/kiosk/settings',{config:c})).config
}

const number = value => Number(value || 0).toLocaleString(props.language==='ru'?'ru-RU':'en-US')
const stamp = value => value ? new Date(value).toLocaleString('ru-RU',{timeZone:'Asia/Tashkent'}) : '—'
const today = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tashkent',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const filters = reactive({from:today(),to:today(),method:'all',offset:0})
const report = ref(null)
async function loadReports() { report.value = await request('/api/owner/reports/summary?'+new URLSearchParams({date_from:filters.from,date_to:filters.to,payment_method:filters.method,sessions_limit:12,sessions_offset:filters.offset})) }
function preset(days) { const d=new Date(today()+'T12:00:00'); d.setDate(d.getDate()-days+1); filters.from=d.toISOString().slice(0,10); filters.to=today(); filters.offset=0; run(loadReports) }
const cardTab=ref('vip')
const cardsAuthority=ref(null)
const canManageCards=computed(()=>!!cardsAuthority.value&&(!cardsAuthority.value.enabled||cardsAuthority.value.local_post===cardsAuthority.value.primary_post))
const cardsPrimaryUrl=computed(()=>cardsAuthority.value?.peer_urls?.[String(cardsAuthority.value?.primary_post)])
async function loadCardsAuthority(){try{cardsAuthority.value=(await request('/api/owner/wallet')).configuration}catch(e){cardsAuthority.value=null;throw e}}
async function requireCardsManagement(){await loadCardsAuthority();if(!canManageCards.value)throw Error(tr('Изменения доступны только на текущем главном посту.','O‘zgartirishlar faqat joriy asosiy postda mavjud.','Changes are available only on the current primary station.'))}
const profiles=ref([]),cards=ref([]),rfid=ref(null),selected=ref(null)
const profileDraft=reactive({code:'',name:'',enabled:true,grant_seconds:60,max_uses_per_day:1,owner_notes:'',device_types:['wash']})
const cardDraft=reactive({uid:'',display_name:'',vip_profile_id:null,status:'active',enabled:true,card_type:'vip',expires_at:null})
async function loadCards() { await loadCardsAuthority(); const [p,c]=await Promise.all([request('/api/owner/vip-profiles'),request('/api/owner/rfid/cards?include_inactive=true')]); profiles.value=p.profiles; cards.value=c.cards }
function editProfile(p) { if(!canManageCards.value)return; Object.keys(profileDraft).forEach(k=>delete profileDraft[k]); Object.assign(profileDraft,p ? {...JSON.parse(JSON.stringify(p)),device_types:p.device_types||['wash']} : {code:'',name:'',enabled:true,grant_seconds:60,max_uses_per_day:1,owner_notes:'',device_types:['wash']}); selected.value='profile' }
function editCard(c) { if(!canManageCards.value)return; Object.assign(cardDraft,{uid:'',display_name:'',vip_profile_id:profiles.value.find(p=>p.enabled)?.id ?? null,status:'active',enabled:true,card_type:'vip',expires_at:null},c || {}); selected.value='card' }
async function readCard() { rfid.value=await request('/api/owner/rfid/latest'); const latest=rfid.value.latest; if(!rfid.value.online) throw Error(tr('Считыватель недоступен','O‘quvchi mavjud emas','Reader unavailable')); if(!latest || Date.now()-new Date(latest.seen_at).getTime()>15000) throw Error(tr('Приложите карту и повторите чтение','Kartani qo‘ying va qayta o‘qing','Present a card and read again')); cardDraft.uid=latest.uid; changed() }
async function saveProfile() { await requireCardsManagement(); await post('/api/owner/vip-profiles',{profiles:[{...profileDraft,max_uses_per_day:profileDraft.max_uses_per_day || null}]}); await loadCards(); selected.value=null }
async function saveCard() { await requireCardsManagement(); await post('/api/owner/rfid/cards',cardDraft); await loadCards(); selected.value=null }
const expiryDate=()=>cardDraft.expires_at?new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tashkent',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(cardDraft.expires_at)):''
function changeExpiry(e){cardDraft.expires_at=e.target.value?e.target.value+'T23:59:59+05:00':null;changed()}
const removeCard=ref(null)
async function removeVip() { await requireCardsManagement(); await request('/api/owner/rfid/cards/'+encodeURIComponent(removeCard.value.uid),{method:'DELETE'}); removeCard.value=null; await loadCards() }
const accountDraft=reactive({login:props.account?.login || '',display_name:props.account?.display_name || '',current_password:'',new_password:'',confirm:''})
async function saveAccount() { if(accountDraft.new_password!==accountDraft.confirm)throw Error(tr('Пароли не совпадают','Parollar mos emas','Passwords do not match')); const {confirm,...body}=accountDraft; if(!body.new_password)delete body.new_password; const result=await post('/api/auth/account',body); emit('account',result); accountDraft.current_password=''; accountDraft.new_password=''; accountDraft.confirm='' }
const configLabels=ref(null)
const config=ref(null),textLanguage=ref('ru'),designTab=ref('brand')
async function loadConfig() { config.value=(await request('/api/kiosk/settings')).config; config.value.theme.design ||= 'cards';config.value.contacts ||= {};config.value.contacts.socialLinks ||= {telegram:'',instagram:'',youtube:''};config.value.contacts.supportPhone ||= '+998 91 111 69 29';config.value.theme.appearance ||= {mode:'auto',manualTheme:'dark',lightStart:'08:00',lightEnd:'18:00',timezone:'Asia/Tashkent'}; for(const p of config.value.programs){p.description ||= {};for(const [i,lang] of ['uz','kz','ky','ru'].entries())if(typeof p.description[lang]!=='string')p.description[lang]=programDescriptions[p.id]?.[i]||''} configLabels.value=JSON.parse(JSON.stringify(config.value)) }
async function upload(event,target,key,kind) { const file=event.target.files?.[0]; if(!file)return; const body=new FormData();body.append('file',file); await run(async()=>{const r=await fetch('/api/kiosk/assets/upload?kind='+kind,{method:'POST',headers:{Authorization:'Bearer '+props.token},body}); const data=await r.json(); if(!r.ok)throw Error(data.detail || 'Upload failed'); target[key]=data.url; changed() }); event.target.value='' }
const telegram=ref(null),botToken=ref(''),pairing=ref(null),confirmReset=ref(false)
async function loadTelegram() { telegram.value=await request('/api/owner/telegram-setup/status') }
async function configureTelegram() { telegram.value=await post('/api/owner/telegram-setup/configure-auto',{token:botToken.value}); botToken.value=''; pairing.value=null }
async function pair(reset=false) { pairing.value=await post('/api/owner/telegram-setup/pairing',{reset_owner:reset}); confirmReset.value=false }
let timer,roleTimer
onMounted(()=>{run(async()=>{ if(props.page==='reports')await loadReports(); if(props.page==='cards')await loadCards(); if(props.page==='kiosk-settings')await loadConfig(); if(props.page==='telegram')await loadTelegram() }); if(props.page==='telegram')timer=setInterval(async()=>{if(busy.value||dirty.value)return; try {telegram.value=await request('/api/owner/telegram-setup/status'); if(telegram.value.owner_paired)pairing.value=null }catch{}},10000) })
onMounted(()=>{if(props.page==='cards')roleTimer=setInterval(()=>{if(!busy.value&&!document.hidden)loadCardsAuthority().catch(()=>{})},10000)})
onUnmounted(()=>{clearInterval(timer);clearInterval(roleTimer)})
</script>
<template>
<section class="owner-page">
  <div class="heading"><h1>{{ tr(...titles[page]) }}</h1><p v-if="page==='reports'">{{ tr('Поступления и использование средств · время Ташкента','Tushum va mablag‘ sarfi · Toshkent vaqti','Receipts and usage · Tashkent time') }}</p></div>
  <div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div>
  <p v-if="busy" class="muted" role="status">{{ tr('Загрузка…','Yuklanmoqda…','Loading…') }}</p>
  <template v-if="page==='reports'">
    <div class="actions" style="margin-bottom:24px"><button class="quiet" @click="reportScope='local'">{{ tr('Этот пост','Ushbu post','This station') }}</button><button class="quiet" @click="reportScope='all'">{{ tr('Все посты','Barcha postlar','All stations') }}</button></div><StationReports v-if="reportScope==='all'" :token="token" :language="language" @dirty="emit('dirty',$event)" /><template v-else>
    <form class="card content" @submit.prevent="filters.offset=0;run(loadReports)"><div class="fields"><label>{{ tr('С даты','Sanadan','From') }}<input v-model="filters.from" type="date" required :max="filters.to" /></label><label>{{ tr('По дату','Sanagacha','To') }}<input v-model="filters.to" type="date" required :min="filters.from" /></label><label>{{ tr('Оплата','To‘lov','Payment') }}<select v-model="filters.method"><option value="all">{{ tr('Все','Barchasi','All') }}</option><option value="cash">{{ tr('Наличные','Naqd','Cash') }}</option><option value="click">Click</option></select></label><div class="actions"><button class="primary" :disabled="busy">{{ tr('Показать','Ko‘rsatish','Show') }}</button><button type="button" class="quiet" @click="preset(1)">{{ tr('Сегодня','Bugun','Today') }}</button><button type="button" class="quiet" @click="preset(7)">7 {{ tr('дней','kun','days') }}</button><button type="button" class="quiet" @click="preset(30)">30 {{ tr('дней','kun','days') }}</button></div></div></form>
    <template v-if="report"><div class="metrics"><section v-for="metric in [[tr('Наличные, сум','Naqd, so‘m','Cash, sum'),report.summary.cash_sum],[tr('Click, сум','Click, so‘m','Click, sum'),report.summary.click_sum],[tr('Денежный расход, сум','Pul sarfi, so‘m','Money spent, sum'),report.summary.spent_sum],[tr('Сеансы','Seanslar','Sessions'),report.summary.sessions]]" class="card metric"><p>{{ metric[0] }}</p><strong>{{ number(metric[1]) }}</strong></section></div>
    <section class="card"><div class="card-head"><h2>{{ tr('Использование программ','Dasturlardan foydalanish','Program usage') }}</h2></div><div class="table-wrap"><table><thead><tr><th>{{ tr('Программа','Dastur','Program') }}</th><th>{{ tr('Минуты','Daqiqa','Minutes') }}</th><th>{{ tr('Денежный расход, сум','Pul sarfi, so‘m','Money spent, sum') }}</th><th>{{ tr('VIP, виртуальные сум','VIP, virtual so‘m','VIP, virtual sum') }}</th></tr></thead><tbody><tr v-for="m in report.modes" :key="m.mode"><th>{{ fieldName(m.mode) }}</th><td>{{ number(Math.round(m.duration_ms/6000)/10) }}</td><td>{{ number(m.spent_sum) }}</td><td>{{ number(m.vip_virtual_spent_sum) }}</td></tr></tbody></table></div><p v-if="!report.modes?.length" class="empty">{{ tr('За этот период данных нет','Bu davr uchun ma’lumot yo‘q','No data for this period') }}</p></section>
    <section class="card"><div class="card-head"><h2>{{ tr('Движение средств на картах','Kartalardagi mablag‘ harakati','Card credit movements') }}</h2></div><div class="content fields"><p>{{ tr('Сохранено','Saqlandi','Saved') }}: {{ number(report.summary.customer_saved_sum) }}</p><p>{{ tr('Использовано','Ishlatildi','Used') }}: {{ number(report.summary.customer_used_sum) }}</p><p>{{ tr('Поступления наличных и Click','Naqd va Click tushumlari','Cash and Click receipts') }}: {{ number(report.summary.external_revenue_sum) }}</p><p>{{ tr('Начислено бонусов','Hisoblangan bonuslar','Bonus awarded') }}: {{ number(report.summary.bonus_granted_sum) }}</p><p>{{ tr('Израсходовано бонусов','Sarflangan bonuslar','Bonus spent') }}: {{ number(report.summary.bonus_spent_sum) }}</p><p>{{ tr('Виртуальный расход VIP','VIP virtual sarfi','VIP virtual usage') }}: {{ number(report.summary.vip_virtual_spent_sum) }}</p><p>VIP: {{ number(report.summary.vip_grant_seconds) }} {{ tr('сек','soniya','sec') }}</p><p>{{ tr('Разница учёта','Hisob farqi','Accounting difference') }}: {{ number(report.summary.credit_difference_sum) }}</p></div></section>
    <section class="card"><div class="card-head"><h2>{{ tr('Сеансы','Seanslar','Sessions') }}</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>{{ tr('Начало','Boshlanish','Started') }}</th><th>{{ tr('Статус','Holat','Status') }}</th><th>{{ tr('Оплачено','To‘landi','Paid') }}</th><th>{{ tr('Остаток','Qoldiq','Remaining') }}</th></tr></thead><tbody><tr v-for="s in report.sessions" :key="s.id"><td>{{ s.id }}</td><td>{{ stamp(s.started_at) }}</td><td>{{ s.status }}</td><td>{{ number(s.paid_sum) }}</td><td>{{ number(s.final_credit_sum) }}</td></tr></tbody></table></div><p v-if="!report.sessions?.length" class="empty">{{ tr('Сеансов нет','Seanslar yo‘q','No sessions') }}</p><div class="content actions end"><button class="quiet" :disabled="!filters.offset || busy" @click="filters.offset-=12;run(loadReports)">←</button><span>{{ report.sessions?.length ? filters.offset+1 : 0 }}–{{ filters.offset+(report.sessions?.length || 0) }}</span><button class="quiet" :disabled="report.sessions?.length<12 || busy" @click="filters.offset+=12;run(loadReports)">→</button></div></section></template>
  </template>
  </template>
  <template v-if="page==='cards'">
    <section v-if="cardsAuthority&&!canManageCards" class="message cards-readonly" role="status"><strong>{{tr('Только просмотр','Faqat ko‘rish','Read only')}}</strong><p>{{tr('Профили VIP, привязка и настройки карт изменяются на текущем главном посту:','VIP profillari, kartalarni biriktirish va sozlash joriy asosiy postda bajariladi:','VIP profiles, card registration and settings are managed on the current primary station:')}} {{cardsAuthority.primary_post}}.</p><StationLink v-if="cardsPrimaryUrl" :href="cardsPrimaryUrl+'/owner/cards'" :language="language">{{tr('Открыть VIP и карты на главном посту','Asosiy postda VIP va kartalarni ochish','Open VIP and cards on the primary station')}}</StationLink></section>

    <div class="actions" style="margin-bottom:24px"><button v-for="tab in (canManageCards?['vip','customer','local','vip-import']:['vip','customer'])" class="quiet" :disabled="busy||dirty" @click="cardTab=tab">{{tab==='vip'?'VIP':tab==='customer'?tr('Денежные карты','Pul kartalari','Customer money cards'):tab==='vip-import'?tr('Перенос VIP','VIP ko‘chirish','Import VIP'):tr('Перенос локальных остатков','Mahalliy qoldiqlarni ko‘chirish','Transfer local balances')}}</button></div>
    <CustomerCards v-if="cardTab!=='vip'&&cardTab!=='vip-import'" :key="cardTab" :token="token" :language="language" :mode="cardTab" :read-only="!canManageCards" @dirty="dirty=$event;emit('dirty',$event)"/>
    <VipMigration v-else-if="cardTab==='vip-import'&&canManageCards" :token="token" :language="language" @dirty="dirty=$event;emit('dirty',$event)"/>
    <template v-else>
    <div class="toolbar"><p>{{ tr('Профиль определяет бесплатное время и дневной лимит VIP-карты.','Profil bepul vaqt va VIP kartaning kunlik limitini belgilaydi.','Profiles define free time and the daily limit for VIP cards.') }}</p><div><button class="quiet" :disabled="!canManageCards || dirty || busy" @click="editProfile()">{{ tr('Добавить профиль','Profil qo‘shish','Add profile') }}</button><button class="primary" :disabled="!canManageCards || dirty || busy || !profiles.length" @click="editCard()">{{ tr('Добавить карту','Karta qo‘shish','Add card') }}</button></div></div>
    <form v-if="canManageCards&&selected==='profile'" class="card content" @submit.prevent="run(saveProfile,true)" @input="changed" @change="changed"><div class="fields"><label>{{ tr('Код','Kod','Code') }}<input v-model="profileDraft.code" maxlength="40" required /></label><label>{{ tr('Название','Nomi','Name') }}<input v-model="profileDraft.name" maxlength="120" required /></label><label>{{ tr('Бесплатное время, сек','Bepul vaqt, soniya','Free time, seconds') }}<input v-model.number="profileDraft.grant_seconds" type="number" min="0" max="86400" required /></label><label>{{ tr('Использований в день (пусто — без лимита)','Kunlik foydalanish (bo‘sh — cheksiz)','Daily uses (empty means unlimited)') }}<input v-model.number="profileDraft.max_uses_per_day" type="number" min="1" max="1000" /></label><fieldset><legend>{{tr('VIP-доступ','VIP ruxsati','VIP access')}}</legend><label class="check"><input type="checkbox" v-model="profileDraft.device_types" value="wash"/>{{tr('Мойка','Yuvish','Wash')}}</label><label class="check"><input type="checkbox" v-model="profileDraft.device_types" value="dry_fog"/>{{tr('Сухой туман','Quruq tuman','Dry fog')}}</label></fieldset><label>{{ tr('Примечание','Izoh','Notes') }}<input v-model="profileDraft.owner_notes" maxlength="500" /></label><label class="check"><input v-model="profileDraft.enabled" type="checkbox" />{{ tr('Включён','Yoqilgan','Enabled') }}</label><div class="actions full"><button class="primary" :disabled="!canManageCards || busy || !dirty || !profileDraft.device_types?.length">{{ tr('Сохранить профиль','Profilni saqlash','Save profile') }}</button></div></div></form>
    <form v-if="canManageCards&&selected==='card'" class="card content" @submit.prevent="run(saveCard,true)" @input="changed" @change="changed"><div class="fields"><label>UID<input v-model="cardDraft.uid" maxlength="64" required /></label><div class="actions"><button type="button" class="quiet" :disabled="busy" @click="run(readCard)">{{ tr('Считать PN532','PN532 o‘qish','Read PN532') }}</button><span class="muted">{{ tr('Приложите карту перед чтением','O‘qishdan oldin kartani qo‘ying','Present a card before reading') }}</span></div><label>{{ tr('Имя владельца карты','Karta egasi','Cardholder') }}<input v-model="cardDraft.display_name" maxlength="120" /></label><label>{{ tr('Профиль','Profil','Profile') }}<select v-model="cardDraft.vip_profile_id" required><option v-for="p in profiles" :value="p.id">{{ p.name }}{{ p.enabled ? '' : ' (OFF)' }}</option></select></label><label>{{ tr('Статус','Holat','Status') }}<select v-model="cardDraft.status"><option value="active">{{ tr('Активна','Faol','Active') }}</option><option value="blocked">{{ tr('Заблокирована','Bloklangan','Blocked') }}</option><option value="lost">{{ tr('Утеряна','Yo‘qolgan','Lost') }}</option><option value="expired">{{ tr('Истекла','Muddati tugagan','Expired') }}</option></select></label><label>{{ tr("Действует до · Ташкент","Amal qilish muddati · Toshkent","Valid until · Tashkent") }}<input type="date" :value="expiryDate()" @input="changeExpiry"/></label><label class="check"><input v-model="cardDraft.enabled" type="checkbox" />{{ tr('Включена','Yoqilgan','Enabled') }}</label><button class="primary" :disabled="!canManageCards || busy || !dirty">{{ tr('Сохранить карту','Kartani saqlash','Save card') }}</button></div></form>
    <section class="card"><div class="card-head"><h2>{{ tr('Профили','Profillar','Profiles') }}</h2></div><div class="table-wrap"><table><thead><tr><th>{{ tr('Название','Nomi','Name') }}</th><th>{{ tr('Секунды','Soniya','Seconds') }}</th><th>{{ tr('Лимит в день','Kunlik limit','Daily limit') }}</th><th>{{ tr('Статус','Holat','Status') }}</th><th></th></tr></thead><tbody><tr v-for="p in profiles" :key="p.id"><th>{{ p.name }}</th><td>{{ p.grant_seconds }}</td><td>{{ p.max_uses_per_day ?? '∞' }}</td><td>{{ p.enabled?'ON':'OFF' }}</td><td><button class="quiet" :disabled="!canManageCards || dirty || busy" @click="editProfile(p)">{{ tr('Изменить','Tahrirlash','Edit') }}</button></td></tr></tbody></table></div><p v-if="!profiles.length" class="empty">{{ tr('Добавьте первый VIP-профиль','Birinchi VIP profilni qo‘shing','Add your first VIP profile') }}</p></section>
    <section class="card"><div class="card-head"><h2>{{ tr('VIP-карты','VIP kartalar','VIP cards') }}</h2></div><div class="table-wrap"><table><thead><tr><th>UID</th><th>{{ tr('Владелец','Egasi','Cardholder') }}</th><th>{{ tr('Статус','Holat','Status') }}</th><th></th></tr></thead><tbody><tr v-for="c in cards" :key="c.uid"><th>{{ c.uid }}</th><td>{{ c.display_name || '—' }}</td><td>{{ c.status }}{{ c.enabled?'':' · OFF' }}<small v-if="c.uses_today!==undefined" style="display:block">{{ tr('Сегодня использовано','Bugun ishlatilgan','Used today') }}: {{ c.uses_today }}<span v-if="c.active_post"> · #{{ c.active_post }}</span></small></td><td><div class="actions"><button class="quiet" :disabled="!canManageCards || dirty || busy" @click="editCard(c)">{{ tr('Изменить','Tahrirlash','Edit') }}</button><button class="quiet" :disabled="!canManageCards || dirty || busy" @click="removeCard=c">{{ tr('Убрать VIP','VIPni olib tashlash','Remove VIP') }}</button></div></td></tr></tbody></table></div><p v-if="!cards.length" class="empty">{{ tr('VIP-карт пока нет','VIP kartalar hali yo‘q','No VIP cards yet') }}</p></section>
    </template>
  </template>
  <form v-if="page==='account'" class="card content" @input="changed" @submit.prevent="run(saveAccount,true)"><div class="fields"><label>{{ tr('Логин','Login','Login') }}<input v-model="accountDraft.login" maxlength="80" required autocomplete="username" /></label><label>{{ tr('Имя','Ism','Name') }}<input v-model="accountDraft.display_name" maxlength="120" /></label><label>{{ tr('Текущий пароль','Joriy parol','Current password') }}<input v-model="accountDraft.current_password" type="password" required autocomplete="current-password" /></label><p class="muted">{{ tr('Для сохранения подтвердите текущий пароль. Новый пароль можно оставить пустым.','Saqlash uchun joriy parolni tasdiqlang. Yangi parolni bo‘sh qoldirish mumkin.','Confirm your current password to save. Leave the new password empty to keep it.') }}</p><label>{{ tr('Новый пароль','Yangi parol','New password') }}<input v-model="accountDraft.new_password" type="password" minlength="8" maxlength="200" autocomplete="new-password" /></label><label>{{ tr('Повторите пароль','Parolni takrorlang','Confirm password') }}<input v-model="accountDraft.confirm" type="password" minlength="8" maxlength="200" autocomplete="new-password" /></label><div class="actions full"><button class="primary" :disabled="busy || !dirty">{{ tr('Сохранить','Saqlash','Save') }}</button></div></div></form>
  <ContactSettings v-if="page==='kiosk-settings'" kind="operator" :token="token" :language="language" @dirty="contactChanged"/>
  <template v-if="page==='kiosk-settings' && config">
    <div class="toolbar"><p>{{ tr('Настройки клиентского экрана. Изменения применяются после сохранения.','Mijoz ekrani sozlamalari. O‘zgarishlar saqlangach qo‘llanadi.','Customer screen settings. Changes apply after saving.') }}</p><button class="primary" :disabled="busy || !dirty" @click="run(saveConfig,true)">{{ tr('Сохранить','Saqlash','Save') }}</button></div>
    <div class="actions" style="margin-bottom:24px"><button v-for="tab in ['brand','programs','texts']" class="quiet" @click="designTab=tab">{{ tab==='brand'?tr('Бренд и оформление','Brend va ko‘rinish','Brand & appearance'):tab==='programs'?tr('Программы','Dasturlar','Programs'):tr('Тексты','Matnlar','Text') }}</button><label><select v-model="textLanguage"><option v-for="lang in ['ru','uz','kz','ky']" :value="lang">{{ lang.toUpperCase() }}</option></select></label></div>
    <section class="card content kiosk-appearance" @input="changed" @change="changed">
      <h2>{{ tr('Вид экрана поста','Post ekrani ko‘rinishi','Station appearance') }}</h2>
      <p class="muted">{{ tr('Dark/Light применяются сразу к экрану клиента. Для Auto настройте часы и сохраните. Ташкент (UTC+5).','Dark/Light mijoz ekraniga darhol qo‘llanadi. Auto uchun vaqtni sozlab saqlang. Toshkent (UTC+5).','Dark/Light apply immediately to the customer screen. For Auto set the hours and save. Tashkent (UTC+5).') }}</p>
      <div class="fields">
        <label>{{ tr("Дизайн экрана","Ekran dizayni","Screen design") }}<select :aria-label="tr('Дизайн экрана','Ekran dizayni','Screen design')" v-model="config.theme.design"><option value="wheel">{{ tr("Круговой","Doiraviy","Wheel") }}</option><option value="cards">{{ tr("Карточки","Kartochkalar","Cards") }}</option></select></label>
        <label>{{ tr('Вид экрана поста','Post ekrani ko‘rinishi','Station appearance') }}<select :aria-label="tr('Вид экрана поста','Post ekrani ko‘rinishi','Station appearance')" :value="appearanceSelection" :disabled="busy" @input.stop @change.stop="applyAppearance"><option value="auto">{{ tr('Auto — автоматически','Auto — Avtomatik','Auto — automatic') }}</option><option value="dark">{{ tr('Dark — тёмный','Dark — To‘q','Dark — dark') }}</option><option value="light">{{ tr('Light — светлый','Light — Och','Light — light') }}</option></select></label>
        <template v-if="appearanceSelection==='auto'"><label>{{ tr('Светлая тема с','Och ko‘rinish boshlanishi','Light theme from') }}<TimeSelect v-model="config.theme.appearance.lightStart" :label="tr('Светлая тема с','Och ko‘rinish boshlanishi','Light theme from')" /></label><label>{{ tr('Тёмная тема с','To‘q ko‘rinish boshlanishi','Dark theme from') }}<TimeSelect v-model="config.theme.appearance.lightEnd" :label="tr('Тёмная тема с','To‘q ko‘rinish boshlanishi','Dark theme from')" /></label></template>
      </div>
      <p v-if="config.theme.appearance.mode==='auto'" class="muted">{{ tr('Вне указанного светлого периода работает тёмная тема. Изменения применяются после сохранения.','Belgilangan yorug‘ davrdan tashqarida to‘q ko‘rinish ishlaydi. O‘zgarishlar saqlangach qo‘llanadi.','Outside the light period the dark theme is used. Changes apply after saving.') }}</p>
    </section>
    <div @input="changed" @change="changed">
    <section v-if="designTab==='brand'" class="card content"><div class="fields">
      <label>{{tr('Название','Nomi','Name')}}<input v-model="config.brand.name" maxlength="60"/></label>
      <label>{{tr('Подпись','Taglavha','Subtitle')}}<input v-model="config.brand.productLine" maxlength="100"/></label>
      <label>{{tr('Логотип, URL','Logotip URL','Logo URL')}}<input v-model="config.brand.logoUrl"/></label>
      <label>{{tr('Загрузить логотип','Logotip yuklash','Upload logo')}}<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,config.brand,'logoUrl','logo')"/></label>
      <label>{{tr('Фото приветственного экрана, URL','Boshlang‘ich ekran rasmi URL','Welcome screen image URL')}}<input v-model="config.layout.backgroundImageUrl"/></label>
      <label>{{tr('Загрузить фото','Rasm yuklash','Upload image')}}<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,config.layout,'backgroundImageUrl','background')"/></label>
      <label>{{tr('Язык по умолчанию','Standart til','Default language')}}<select v-model="config.layout.defaultLanguage"><option v-for="lang in ['uz','ru','kz','ky']" :value="lang">{{lang.toUpperCase()}}</option></select></label>
      <label class="check"><input v-model="config.layout.showLanguageButtons" type="checkbox"/>{{tr('Показывать языки','Tillarni ko‘rsatish','Show language buttons')}}</label>
      <label>{{tr('Минимальная сумма оплаты','Minimal to‘lov','Minimum payment')}}<input v-model.number="config.payment.minAmount" type="number" min="1"/></label>
      <label>{{tr('Максимальная сумма оплаты','Maksimal to‘lov','Maximum payment')}}<input v-model.number="config.payment.maxAmount" type="number" min="1"/></label>
      <label v-for="(_,i) in config.payment.quickAmounts">{{tr('Быстрая сумма','Tezkor summa','Quick amount')}} {{i+1}}<input v-model.number="config.payment.quickAmounts[i]" type="number" min="1"/></label>
    </div><p class="muted">{{tr('Название, подпись и логотип применяются к обоим дизайнам и заставке. Фото — только к заставке. Новый язык применяется для нового посетителя.','Nom, taglavha va logotip ikkala dizayn va boshlang‘ich ekranga qo‘llanadi. Rasm faqat boshlang‘ich ekran uchun. Til yangi mijoz uchun qo‘llanadi.','Name, subtitle and logo apply to both designs and the welcome screen. The image is for the welcome screen. Language applies to new visitors.')}}</p></section>
    <div v-if="designTab==='programs'" class="programs-edit"><section v-for="p in config.programs" :key="p.id" class="card program-edit"><h3>{{p.label[language]||p.label.ru||p.id}}</h3><label>{{tr('Название','Nomi','Name')}} · {{textLanguage.toUpperCase()}}<input v-model="p.label[textLanguage]"/></label><label>{{tr('Подзаголовок','Qisqa tavsif','Subtitle')}} · {{textLanguage.toUpperCase()}}<input v-model="p.description[textLanguage]" maxlength="80"/></label><small class="muted">{{tr('Короткое описание под названием. Оставьте пустым, чтобы скрыть.','Nom ostidagi qisqa tavsif. Yashirish uchun bo‘sh qoldiring.','Short description below the name. Leave blank to hide.')}}</small><label class="check"><input v-model="p.visible" type="checkbox"/>{{tr('Видна','Ko‘rinadi','Visible')}}</label></section></div>
    <section v-if="designTab==='texts'" class="card content"><p>{{tr('Сообщения состояния и оплаты используют проверенные переводы UZ / KZ / KY / RU. Старый редактор текстов, цветов и иконок скрыт: эти поля не управляли текущими дизайнами. Названия программ доступны на вкладке «Программы».','Holat va to‘lov xabarlari UZ / KZ / KY / RU tarjimalaridan foydalanadi. Joriy dizaynlarga ta’sir qilmagan eski matn, rang va belgi maydonlari yashirildi. Dastur nomlari «Dasturlar»da.','Status and payment messages use verified UZ / KZ / KY / RU translations. Legacy text, color and icon fields that did not control these designs are hidden. Program names remain under Programs.')}}</p></section>
    </div>
  </template>
  <template v-if="page==='telegram' && telegram"><p v-if="telegram.manage_allowed===false" class="message">{{tr('Настройка Telegram выполняется на главном посту:','Telegram asosiy postda sozlanadi:','Configure Telegram on the primary station:')}} {{telegram.primary_post}}.</p>
    <section class="card content"><h2>{{ telegram.configured ? '@'+telegram.bot_username : tr('Подключение бота','Botni ulash','Connect a bot') }}</h2><p class="muted">{{ telegram.owner_paired ? tr('Владелец привязан','Egasi ulangan','Owner paired')+' · '+telegram.owner_name : tr('Владелец ещё не привязан','Egasi hali ulanmagan','Owner not paired yet') }} · {{ telegram.enabled ? 'Online' : 'Offline' }}</p><form @submit.prevent="run(configureTelegram,true)"><fieldset :disabled="telegram.manage_allowed===false" style="border:0;padding:0;margin:0;min-width:0"><label>BotFather token<input v-model="botToken" type="password" autocomplete="off" required maxlength="256" @input="changed" /></label><div class="actions" style="margin-top:20px"><button class="primary" :disabled="busy || !botToken">{{ tr('Проверить и подключить','Tekshirish va ulash','Verify & connect') }}</button><button type="button" class="quiet" :disabled="busy || !telegram.enabled" @click="telegram.owner_paired ? confirmReset=true : run(()=>pair())">{{ tr('Привязать владельца','Egasini ulash','Pair owner') }}</button><button type="button" class="quiet" :disabled="busy || !telegram.enabled" @click="run(async()=>{telegram=await post('/api/owner/telegram-setup/disable',{});pairing=null})">{{ tr('Отключить бота','Botni o‘chirish','Disable bot') }}</button></div></fieldset></form><div v-if="pairing"><p>{{ tr('Отсканируйте QR и нажмите Start в Telegram.','QRni skanerlang va Telegramda Start bosing.','Scan the QR and press Start in Telegram.') }} {{ tr('Действует до','Amal qilish muddati','Expires') }} {{ stamp(pairing.expires_at) }}</p><img class="pairing-qr" :src="pairing.qr_data_url" alt="Telegram pairing QR" /></div></section>
    <section class="card content"><h2>{{ tr('Посты мойки','Yuvish postlari','Wash stations') }}</h2><p class="muted">{{ tr('Автоматический поиск постов этой мойки в локальной сети. На каждом посте должен быть установлен Report API и задан свой номер при установке. Отчёт — ежедневно в 21:00 по Ташкенту.','Mahalliy tarmoqda ushbu yuvish postlarini avtomatik qidirish. Har bir postda Report API o‘rnatilgan va post raqami belgilangan bo‘lishi kerak. Hisobot har kuni Toshkent vaqti bilan 21:00 da.','Automatically discover this site’s stations on the LAN. Each station needs Report API and its own station number from installation. Daily report at 21:00 Tashkent time.') }}</p><div v-if="!telegram.identity_configured" class="message error">{{ tr('Не задана мойка и номер поста. Сначала выполните установку поста.','Yuvish va post raqami belgilanmagan. Avval postni sozlang.','Site identity is not configured. Complete station installation first.') }}</div><button class="primary" :disabled="busy || !telegram.identity_configured || telegram.manage_allowed===false" @click="run(async()=>{await post('/api/owner/telegram-setup/discover',{});await loadTelegram()})">{{ tr('Найти посты автоматически','Postlarni avtomatik topish','Discover stations') }}</button><div class="table-wrap"><table><thead><tr><th>{{ tr('Пост','Post','Station') }}</th><th>IP</th></tr></thead><tbody><tr v-for="p in telegram.posts" :key="p.id"><th>{{ p.name }}</th><td>{{ p.host }}</td></tr></tbody></table></div></section>
  </template>
  <div v-if="removeCard || confirmReset" class="confirm-backdrop"><section class="card confirm-dialog" role="alertdialog" aria-modal="true"><h2>{{ removeCard ? tr('Убрать VIP-доступ? Карта станет клиентской.','VIP kirishni olib tashlashmi? Karta mijoz kartasiga aylanadi.','Remove VIP access? This becomes a customer card.') : tr('Отвязать прежнего владельца Telegram?','Oldingi Telegram egasini uzishmi?','Unpair the previous Telegram owner?') }}</h2><div class="actions"><button class="quiet" @click="removeCard=null;confirmReset=false">{{ tr('Отмена','Bekor qilish','Cancel') }}</button><button class="primary" :disabled="busy" @click="run(removeCard ? removeVip : ()=>pair(true))">{{ tr('Подтвердить','Tasdiqlash','Confirm') }}</button></div></section></div>
</section>
</template>
